-- STEP 1: INITIAL SCHEMA (8 TABLES, CONSTRAINTS, INDEXES)
-- =============================================================================
-- Migration: 20261006000001_initial_schema.sql
-- Description: Baseline schema for Kola Express delivery management platform.
-- Safe, non-destructive, idempotent DDL preserving existing Kola Express structure.
-- =============================================================================

-- Ensure UUID and pgcrypto extensions are available if needed
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- -----------------------------------------------------------------------------
-- 1. USERS TABLE
-- Stores customers, couriers, and administrators
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.users (
    
    id BIGSERIAL PRIMARY KEY,
    full_name TEXT NOT NULL,
    phone TEXT UNIQUE,
    email TEXT UNIQUE,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'customer' CHECK (role IN ('customer', 'courier', 'admin')),
    admin_role TEXT DEFAULT 'super_admin' CHECK (admin_role IN ('super_admin', 'operations_admin', 'finance_admin')),
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- -----------------------------------------------------------------------------
-- 2. COURIERS TABLE
-- Stores active delivery riders / drivers and vehicle info
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.couriers (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT REFERENCES public.users(id) ON DELETE SET NULL,
    full_name TEXT NOT NULL,
    phone TEXT UNIQUE NOT NULL,
    vehicle_type TEXT DEFAULT 'Boda Boda (Motorcycle)',
    plate_number TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'busy', 'offline')),
    rating NUMERIC(3, 2) DEFAULT 4.90,
    total_trips INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- -----------------------------------------------------------------------------
-- 3. PRICING RULES TABLE
-- Baseline pricing configuration for Kola Express delivery engine
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.pricing_rules (
    id BIGSERIAL PRIMARY KEY,
    base_fee BIGINT NOT NULL DEFAULT 4000,
    per_km_rate BIGINT NOT NULL DEFAULT 800,
    min_fee BIGINT NOT NULL DEFAULT 3500,
    urgent_surcharge BIGINT NOT NULL DEFAULT 3000,
    category_surcharges JSONB NOT NULL DEFAULT '{"document":0,"small_parcel":0,"medium_box":0,"large_package":0,"groceries":0,"fragile":0}'::jsonb,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- -----------------------------------------------------------------------------
-- 4. DELIVERIES TABLE
-- Core delivery tracking & dispatch records
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.deliveries (
    id BIGSERIAL PRIMARY KEY,
    tracking_number TEXT UNIQUE NOT NULL,
    customer_id BIGINT REFERENCES public.users(id) ON DELETE SET NULL,
    sender_name TEXT NOT NULL,
    sender_phone TEXT NOT NULL,
    pickup_location TEXT NOT NULL,
    pickup_directions TEXT,
    pickup_notes TEXT,
    recipient_name TEXT NOT NULL,
    recipient_phone TEXT NOT NULL,
    delivery_location TEXT NOT NULL,
    delivery_directions TEXT,
    delivery_notes TEXT,
    item_description TEXT NOT NULL,
    item_category TEXT NOT NULL DEFAULT 'small_parcel',
    special_instructions TEXT,
    is_urgent INTEGER DEFAULT 0,
    distance_km NUMERIC(8, 2) NOT NULL DEFAULT 5.00,
    delivery_fee BIGINT NOT NULL,
    status TEXT NOT NULL DEFAULT 'Awaiting Payment',
    courier_id BIGINT REFERENCES public.couriers(id) ON DELETE SET NULL,
    courier_assigned_at TIMESTAMPTZ,
    courier_arrived_at TIMESTAMPTZ,
    picked_up_at TIMESTAMPTZ,
    delivered_at TIMESTAMPTZ,
    handover_confirmed_at TIMESTAMPTZ,
    handover_confirmation_id TEXT,
    handover_sender_id BIGINT REFERENCES public.users(id) ON DELETE SET NULL,
    handover_status TEXT,
    handover_notes TEXT,
    courier_confirmed_at TIMESTAMPTZ,
    courier_confirmed_received INTEGER DEFAULT 0,
    delivery_pin TEXT,
    pin_verified_at TIMESTAMPTZ,
    delivery_confirmed_by_pin INTEGER DEFAULT 0,
    pickup_lat NUMERIC(10, 7),
    pickup_lng NUMERIC(10, 7),
    delivery_lat NUMERIC(10, 7),
    delivery_lng NUMERIC(10, 7),
    eta_minutes INTEGER,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- -----------------------------------------------------------------------------
-- 5. HANDOVER CONFIRMATIONS TABLE
-- Digital receipt and package verification handoff
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.handover_confirmations (
    id BIGSERIAL PRIMARY KEY,
    handover_id TEXT UNIQUE NOT NULL,
    delivery_id BIGINT NOT NULL REFERENCES public.deliveries(id) ON DELETE CASCADE,
    tracking_number TEXT NOT NULL,
    sender_id BIGINT REFERENCES public.users(id) ON DELETE SET NULL,
    sender_name TEXT NOT NULL,
    sender_phone TEXT NOT NULL,
    courier_id BIGINT REFERENCES public.couriers(id) ON DELETE SET NULL,
    courier_name TEXT NOT NULL,
    courier_phone TEXT NOT NULL,
    courier_arrived_at TIMESTAMPTZ,
    confirmed_at TIMESTAMPTZ,
    previous_status TEXT NOT NULL DEFAULT 'Awaiting Sender Confirmation',
    new_status TEXT NOT NULL DEFAULT 'Package Picked Up',
    confirmation_type TEXT NOT NULL DEFAULT 'sender_digital_handover',
    status TEXT NOT NULL DEFAULT 'confirmed',
    notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- -----------------------------------------------------------------------------
-- 6. DELIVERY STATUS HISTORY TABLE
-- Audit trail of transitions for real-time tracking
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.delivery_status_history (
    id BIGSERIAL PRIMARY KEY,
    delivery_id BIGINT NOT NULL REFERENCES public.deliveries(id) ON DELETE CASCADE,
    status TEXT NOT NULL,
    note TEXT,
    updated_by TEXT DEFAULT 'System',
    timestamp TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

-- Ensure nullable for historical SQLite compatibility if table already created
ALTER TABLE IF EXISTS public.delivery_status_history ALTER COLUMN timestamp DROP NOT NULL;

-- -----------------------------------------------------------------------------
-- 7. PAYMENTS TABLE
-- Mobile money (MTN / Airtel) cashless payment transactions
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.payments (
    id BIGSERIAL PRIMARY KEY,
    delivery_id BIGINT NOT NULL REFERENCES public.deliveries(id) ON DELETE CASCADE,
    tracking_number TEXT NOT NULL,
    amount BIGINT NOT NULL,
    currency TEXT DEFAULT 'UGX',
    payment_method TEXT NOT NULL,
    customer_phone TEXT NOT NULL,
    reference_id TEXT UNIQUE NOT NULL,
    payment_status TEXT NOT NULL DEFAULT 'Pending' CHECK (payment_status IN ('Pending', 'Successful', 'Failed')),
    provider_response TEXT,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    confirmed_at TIMESTAMPTZ
);

ALTER TABLE IF EXISTS public.payments ALTER COLUMN created_at DROP NOT NULL;

-- -----------------------------------------------------------------------------
-- 8. ADMIN LOGS TABLE
-- Security audit trail for admin actions
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.admin_logs (
    id BIGSERIAL PRIMARY KEY,
    admin_id BIGINT REFERENCES public.users(id) ON DELETE SET NULL,
    admin_name TEXT NOT NULL,
    admin_role TEXT DEFAULT 'super_admin',
    action TEXT NOT NULL,
    resource TEXT,
    resource_id TEXT,
    details TEXT,
    timestamp TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- -----------------------------------------------------------------------------
-- INDEXES FOR PERFORMANCE AND RELIABILITY
-- -----------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_users_phone ON public.users(phone);
CREATE INDEX IF NOT EXISTS idx_users_email ON public.users(email);
CREATE INDEX IF NOT EXISTS idx_users_role ON public.users(role);

CREATE INDEX IF NOT EXISTS idx_couriers_user_id ON public.couriers(user_id);
CREATE INDEX IF NOT EXISTS idx_couriers_status ON public.couriers(status);

CREATE INDEX IF NOT EXISTS idx_deliveries_tracking_number ON public.deliveries(tracking_number);
CREATE INDEX IF NOT EXISTS idx_deliveries_customer_id ON public.deliveries(customer_id);
CREATE INDEX IF NOT EXISTS idx_deliveries_courier_id ON public.deliveries(courier_id);
CREATE INDEX IF NOT EXISTS idx_deliveries_status ON public.deliveries(status);
CREATE INDEX IF NOT EXISTS idx_deliveries_created_at ON public.deliveries(created_at DESC);

CREATE INDEX IF NOT EXISTS idx_handover_delivery_id ON public.handover_confirmations(delivery_id);
CREATE INDEX IF NOT EXISTS idx_handover_tracking ON public.handover_confirmations(tracking_number);

CREATE INDEX IF NOT EXISTS idx_status_history_delivery_id ON public.delivery_status_history(delivery_id);
CREATE INDEX IF NOT EXISTS idx_payments_delivery_id ON public.payments(delivery_id);
CREATE INDEX IF NOT EXISTS idx_payments_reference_id ON public.payments(reference_id);
CREATE INDEX IF NOT EXISTS idx_payments_tracking ON public.payments(tracking_number);

CREATE INDEX IF NOT EXISTS idx_admin_logs_timestamp ON public.admin_logs(timestamp DESC);


-- STEP 2: DELIVERY PRICING ENGINE (17 FIELDS & SYNC TRIGGERS)
-- =============================================================================
-- Migration: 20261006000002_delivery_pricing_engine.sql
-- Description: Authoritative Delivery Pricing & Road Routing Specification.
-- Adds 17 dedicated fields for exact road calculation, coordinates, fees,
-- routing engine provenance, and pricing version audit.
-- Safe, non-destructive, and backward-compatible with automatic sync triggers.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. ADD NEW DELIVERY PRICING & ROUTING COLUMNS
-- -----------------------------------------------------------------------------
ALTER TABLE public.deliveries 
    ADD COLUMN IF NOT EXISTS pickup_address TEXT,
    ADD COLUMN IF NOT EXISTS pickup_latitude NUMERIC(10, 7),
    ADD COLUMN IF NOT EXISTS pickup_longitude NUMERIC(10, 7),
    ADD COLUMN IF NOT EXISTS dropoff_address TEXT,
    ADD COLUMN IF NOT EXISTS dropoff_latitude NUMERIC(10, 7),
    ADD COLUMN IF NOT EXISTS dropoff_longitude NUMERIC(10, 7),
    ADD COLUMN IF NOT EXISTS road_distance NUMERIC(10, 2),
    ADD COLUMN IF NOT EXISTS estimated_travel_time INTEGER,
    ADD COLUMN IF NOT EXISTS base_delivery_fee NUMERIC(12, 2) DEFAULT 4000,
    ADD COLUMN IF NOT EXISTS distance_fee NUMERIC(12, 2) DEFAULT 0,
    ADD COLUMN IF NOT EXISTS surcharges NUMERIC(12, 2) DEFAULT 0,
    ADD COLUMN IF NOT EXISTS discounts NUMERIC(12, 2) DEFAULT 0,
    ADD COLUMN IF NOT EXISTS final_delivery_fee NUMERIC(12, 2),
    ADD COLUMN IF NOT EXISTS pricing_version VARCHAR(50) DEFAULT 'v1.0',
    ADD COLUMN IF NOT EXISTS routing_provider VARCHAR(50) DEFAULT 'osrm',
    ADD COLUMN IF NOT EXISTS route_reference VARCHAR(255),
    ADD COLUMN IF NOT EXISTS pricing_calculation_timestamp TIMESTAMPTZ DEFAULT timezone('utc'::text, now());

-- -----------------------------------------------------------------------------
-- 2. BACKFILL EXISTING RECORDS SAFELY
-- Ensures historical deliveries immediately populate the new pricing schema
-- -----------------------------------------------------------------------------
UPDATE public.deliveries
SET 
    pickup_address = COALESCE(pickup_address, pickup_location),
    pickup_latitude = COALESCE(pickup_latitude, pickup_lat),
    pickup_longitude = COALESCE(pickup_longitude, pickup_lng),
    dropoff_address = COALESCE(dropoff_address, delivery_location),
    dropoff_latitude = COALESCE(dropoff_latitude, delivery_lat),
    dropoff_longitude = COALESCE(dropoff_longitude, delivery_lng),
    road_distance = COALESCE(road_distance, distance_km),
    estimated_travel_time = COALESCE(estimated_travel_time, eta_minutes),
    final_delivery_fee = COALESCE(final_delivery_fee, delivery_fee),
    base_delivery_fee = COALESCE(base_delivery_fee, 4000),
    distance_fee = COALESCE(distance_fee, GREATEST(0, delivery_fee - 4000)),
    surcharges = COALESCE(surcharges, CASE WHEN is_urgent = 1 THEN 3000 ELSE 0 END),
    discounts = COALESCE(discounts, 0),
    pricing_version = COALESCE(pricing_version, 'v1.0'),
    routing_provider = COALESCE(routing_provider, 'osrm'),
    pricing_calculation_timestamp = COALESCE(pricing_calculation_timestamp, created_at)
WHERE 
    pickup_address IS NULL 
    OR dropoff_address IS NULL 
    OR final_delivery_fee IS NULL;

-- -----------------------------------------------------------------------------
-- 3. BIDIRECTIONAL SYNC TRIGGER FOR SEAMLESS BACKWARD & FORWARD COMPATIBILITY
-- Automatically synchronizes legacy and modern pricing fields on insert/update
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_sync_delivery_pricing_fields()
RETURNS TRIGGER AS $$
BEGIN
    -- Sync Pickup
    IF NEW.pickup_address IS NULL AND NEW.pickup_location IS NOT NULL THEN
        NEW.pickup_address := NEW.pickup_location;
    ELSIF NEW.pickup_location IS NULL AND NEW.pickup_address IS NOT NULL THEN
        NEW.pickup_location := NEW.pickup_address;
    END IF;

    IF NEW.pickup_latitude IS NULL AND NEW.pickup_lat IS NOT NULL THEN
        NEW.pickup_latitude := NEW.pickup_lat;
    ELSIF NEW.pickup_lat IS NULL AND NEW.pickup_latitude IS NOT NULL THEN
        NEW.pickup_lat := NEW.pickup_latitude;
    END IF;

    IF NEW.pickup_longitude IS NULL AND NEW.pickup_lng IS NOT NULL THEN
        NEW.pickup_longitude := NEW.pickup_lng;
    ELSIF NEW.pickup_lng IS NULL AND NEW.pickup_longitude IS NOT NULL THEN
        NEW.pickup_lng := NEW.pickup_longitude;
    END IF;

    -- Sync Dropoff
    IF NEW.dropoff_address IS NULL AND NEW.delivery_location IS NOT NULL THEN
        NEW.dropoff_address := NEW.delivery_location;
    ELSIF NEW.delivery_location IS NULL AND NEW.dropoff_address IS NOT NULL THEN
        NEW.delivery_location := NEW.dropoff_address;
    END IF;

    IF NEW.dropoff_latitude IS NULL AND NEW.delivery_lat IS NOT NULL THEN
        NEW.dropoff_latitude := NEW.delivery_lat;
    ELSIF NEW.delivery_lat IS NULL AND NEW.dropoff_latitude IS NOT NULL THEN
        NEW.delivery_lat := NEW.dropoff_latitude;
    END IF;

    IF NEW.dropoff_longitude IS NULL AND NEW.delivery_lng IS NOT NULL THEN
        NEW.dropoff_longitude := NEW.delivery_lng;
    ELSIF NEW.delivery_lng IS NULL AND NEW.dropoff_longitude IS NOT NULL THEN
        NEW.delivery_lng := NEW.dropoff_longitude;
    END IF;

    -- Sync Road Distance & Travel Time
    IF NEW.road_distance IS NULL AND NEW.distance_km IS NOT NULL THEN
        NEW.road_distance := NEW.distance_km;
    ELSIF NEW.distance_km IS NULL AND NEW.road_distance IS NOT NULL THEN
        NEW.distance_km := NEW.road_distance;
    END IF;

    IF NEW.estimated_travel_time IS NULL AND NEW.eta_minutes IS NOT NULL THEN
        NEW.estimated_travel_time := NEW.eta_minutes;
    ELSIF NEW.eta_minutes IS NULL AND NEW.estimated_travel_time IS NOT NULL THEN
        NEW.eta_minutes := NEW.estimated_travel_time;
    END IF;

    -- Sync Delivery Fees
    IF NEW.final_delivery_fee IS NULL AND NEW.delivery_fee IS NOT NULL THEN
        NEW.final_delivery_fee := NEW.delivery_fee;
    ELSIF NEW.delivery_fee IS NULL AND NEW.final_delivery_fee IS NOT NULL THEN
        NEW.delivery_fee := ROUND(NEW.final_delivery_fee)::BIGINT;
    END IF;

    -- Default pricing metadata if missing
    IF NEW.pricing_version IS NULL THEN
        NEW.pricing_version := 'v1.0';
    END IF;
    IF NEW.routing_provider IS NULL THEN
        NEW.routing_provider := 'osrm';
    END IF;
    IF NEW.pricing_calculation_timestamp IS NULL THEN
        NEW.pricing_calculation_timestamp := timezone('utc'::text, now());
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_sync_delivery_pricing_fields ON public.deliveries;
CREATE TRIGGER trg_sync_delivery_pricing_fields
    BEFORE INSERT OR UPDATE ON public.deliveries
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_sync_delivery_pricing_fields();

-- -----------------------------------------------------------------------------
-- 4. PERFORMANCE & AUDIT INDEXES
-- -----------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_deliveries_pricing_calc 
    ON public.deliveries(pricing_calculation_timestamp DESC);

CREATE INDEX IF NOT EXISTS idx_deliveries_routing_provider 
    ON public.deliveries(routing_provider);

CREATE INDEX IF NOT EXISTS idx_deliveries_pricing_version 
    ON public.deliveries(pricing_version);


-- STEP 3: ROW LEVEL SECURITY & ACCESS POLICIES
-- =============================================================================
-- Migration: 20261006000003_rls_and_security_policies.sql
-- Description: Row Level Security (RLS) and Granular Access Policies for Supabase.
-- Ensures data isolation while permitting public parcel tracking,
-- customer access, courier updates, and administrative management.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. ENABLE ROW LEVEL SECURITY ACROSS ALL TABLES
-- -----------------------------------------------------------------------------
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.couriers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pricing_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.deliveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.handover_confirmations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.delivery_status_history ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.admin_logs ENABLE ROW LEVEL SECURITY;

-- -----------------------------------------------------------------------------
-- 2. PRICING RULES POLICIES
-- Anyone can view current pricing rules to get rate estimates
-- -----------------------------------------------------------------------------
DROP POLICY IF EXISTS "Public can view pricing rules" ON public.pricing_rules;
CREATE POLICY "Public can view pricing rules" 
    ON public.pricing_rules FOR SELECT 
    USING (true);

DROP POLICY IF EXISTS "Admins manage pricing rules" ON public.pricing_rules;
CREATE POLICY "Admins manage pricing rules" 
    ON public.pricing_rules FOR ALL 
    USING (
        auth.role() = 'service_role' 
        OR EXISTS (
            SELECT 1 FROM public.users 
            WHERE users.id::text = auth.uid()::text AND users.role = 'admin'
        )
    );

-- -----------------------------------------------------------------------------
-- 3. DELIVERIES POLICIES
-- Tracking requires tracking number; authenticated users see their orders
-- -----------------------------------------------------------------------------
DROP POLICY IF EXISTS "Public can track package with tracking number" ON public.deliveries;
CREATE POLICY "Public can track package with tracking number" 
    ON public.deliveries FOR SELECT 
    USING (tracking_number IS NOT NULL);

DROP POLICY IF EXISTS "Customers view their own orders" ON public.deliveries;
CREATE POLICY "Customers view their own orders" 
    ON public.deliveries FOR SELECT 
    USING (
        customer_id::text = auth.uid()::text 
        OR auth.role() = 'service_role'
    );

DROP POLICY IF EXISTS "Couriers view assigned deliveries" ON public.deliveries;
CREATE POLICY "Couriers view assigned deliveries" 
    ON public.deliveries FOR SELECT 
    USING (
        courier_id IN (
            SELECT id FROM public.couriers WHERE user_id::text = auth.uid()::text
        )
        OR auth.role() = 'service_role'
    );

DROP POLICY IF EXISTS "Service role and backend have full access to deliveries" ON public.deliveries;
CREATE POLICY "Service role and backend have full access to deliveries" 
    ON public.deliveries FOR ALL 
    USING (auth.role() = 'service_role' OR auth.jwt() IS NOT NULL);

-- -----------------------------------------------------------------------------
-- 4. COURIERS POLICIES
-- -----------------------------------------------------------------------------
DROP POLICY IF EXISTS "Public can view active couriers" ON public.couriers;
CREATE POLICY "Public can view active couriers" 
    ON public.couriers FOR SELECT 
    USING (true);

DROP POLICY IF EXISTS "Couriers update own record" ON public.couriers;
CREATE POLICY "Couriers update own record" 
    ON public.couriers FOR UPDATE 
    USING (
        user_id::text = auth.uid()::text 
        OR auth.role() = 'service_role'
    );

DROP POLICY IF EXISTS "Admins have full access to couriers" ON public.couriers;
CREATE POLICY "Admins have full access to couriers" 
    ON public.couriers FOR ALL 
    USING (auth.role() = 'service_role');

-- -----------------------------------------------------------------------------
-- 5. HANDOVER CONFIRMATIONS POLICIES
-- -----------------------------------------------------------------------------
DROP POLICY IF EXISTS "Handover participants can view handover" ON public.handover_confirmations;
CREATE POLICY "Handover participants can view handover" 
    ON public.handover_confirmations FOR SELECT 
    USING (true);

DROP POLICY IF EXISTS "Authorized participants can create handover" ON public.handover_confirmations;
CREATE POLICY "Authorized participants can create handover" 
    ON public.handover_confirmations FOR INSERT 
    WITH CHECK (true);

DROP POLICY IF EXISTS "Service role manages handovers" ON public.handover_confirmations;
CREATE POLICY "Service role manages handovers" 
    ON public.handover_confirmations FOR ALL 
    USING (auth.role() = 'service_role');

-- -----------------------------------------------------------------------------
-- 6. DELIVERY STATUS HISTORY POLICIES
-- -----------------------------------------------------------------------------
DROP POLICY IF EXISTS "Public can view delivery status history" ON public.delivery_status_history;
CREATE POLICY "Public can view delivery status history" 
    ON public.delivery_status_history FOR SELECT 
    USING (true);

DROP POLICY IF EXISTS "Service role manages status history" ON public.delivery_status_history;
CREATE POLICY "Service role manages status history" 
    ON public.delivery_status_history FOR ALL 
    USING (auth.role() = 'service_role');

-- -----------------------------------------------------------------------------
-- 7. PAYMENTS POLICIES
-- -----------------------------------------------------------------------------
DROP POLICY IF EXISTS "Public can view payment by tracking or reference" ON public.payments;
CREATE POLICY "Public can view payment by tracking or reference" 
    ON public.payments FOR SELECT 
    USING (true);

DROP POLICY IF EXISTS "Service role manages payments" ON public.payments;
CREATE POLICY "Service role manages payments" 
    ON public.payments FOR ALL 
    USING (auth.role() = 'service_role');

-- -----------------------------------------------------------------------------
-- 8. USERS & ADMIN LOGS POLICIES
-- -----------------------------------------------------------------------------
DROP POLICY IF EXISTS "Users can read own profile" ON public.users;
CREATE POLICY "Users can read own profile" 
    ON public.users FOR SELECT 
    USING (id::text = auth.uid()::text OR auth.role() = 'service_role');

DROP POLICY IF EXISTS "Service role manages users" ON public.users;
CREATE POLICY "Service role manages users" 
    ON public.users FOR ALL 
    USING (auth.role() = 'service_role');

DROP POLICY IF EXISTS "Service role manages admin logs" ON public.admin_logs;
CREATE POLICY "Service role manages admin logs" 
    ON public.admin_logs FOR ALL 
    USING (auth.role() = 'service_role');


